package com.skillrental.controller;
import com.skillrental.service.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import org.springframework.ui.Model;
import org.springframework.format.annotation.DateTimeFormat;import java.time.*;import java.util.*;
@Controller @RequiredArgsConstructor
public class SupportManagementController {
 private final PrivateFileStorage storage;private final ChatService chat;private final CurrentUserService current;private final SupportManagementService support;private final ConversationReviewService reviews;
 @GetMapping("/admin/support/search") @ResponseBody public Object search(Authentication a,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="") String status,@RequestParam(required=false) Long assignee,
  @RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return support.search(current.require(a),q,status,assignee,from,to).stream().map(row->{var c=row.conversation();var u=c.getCustomer()!=null?c.getCustomer():c.getProvider();return Map.of("id",c.getId(),"name",u.getFullName(),"role",u.getRole().name(),"status",c.getSupportStatus(),"assignee",c.getSupportAdmin()==null?"Chưa phân công":c.getSupportAdmin().getFullName(),"lastContent",row.lastContent(),"unread",row.unreadCount(),"lastAt",c.getLastMessageAt().toString(),"orderId",c.getOrder()==null?0:c.getOrder().getId(),"complaintId",c.getLinkedComplaint()==null?0:c.getLinkedComplaint().getId());}).toList();}
 @GetMapping("/admin/support/{id}/notes") @ResponseBody public Object notes(@PathVariable Long id,Authentication a){return support.notes(id,current.require(a));}
 @PostMapping("/admin/support/{id}/notes") @ResponseBody public Object note(@PathVariable Long id,@RequestParam String content,Authentication a){support.note(id,current.require(a),content);return Map.of("success",true);}
 @PostMapping("/admin/support/{id}/metadata") @ResponseBody public Object update(@PathVariable Long id,Authentication a,@RequestParam String status,@RequestParam(required=false) Long orderId,@RequestParam(required=false) Long complaintId){support.update(id,current.require(a),status,orderId,complaintId);return Map.of("success",true);}
 @PostMapping("/admin/support/{id}/transfer") @ResponseBody public Object transfer(@PathVariable Long id,Authentication a,@RequestParam Long adminId,@RequestParam String reason){chat.transferSupport(id,current.require(a),adminId,reason);return Map.of("success",true);}
 @GetMapping("/admin/support-reviews") public String page(Authentication a,Model model){var u=current.require(a);support.admin(u);model.addAttribute("canApprove",reviews.canApprove(u));return "workspace/admin/support-reviews";}
 @GetMapping("/admin/support-reviews/list") @ResponseBody public Object grants(Authentication a){return reviews.list(current.require(a));}
 @PostMapping("/admin/support-reviews") @ResponseBody public Object request(Authentication a,@RequestParam Long conversationId,@RequestParam Long complaintId,@RequestParam String reason,
 @RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME) LocalDateTime to){return Map.of("id",reviews.request(current.require(a),conversationId,complaintId,reason,from,to).getId());}
 @PostMapping("/admin/support-reviews/{id}/decision") @ResponseBody public Object decide(@PathVariable Long id,Authentication a,@RequestParam boolean approve,@RequestParam(defaultValue="false") boolean exportAllowed,@RequestParam String reason){reviews.decide(id,current.require(a),approve,exportAllowed,reason);return Map.of("success",true);}
 @GetMapping("/admin/support-reviews/{id}/messages") @ResponseBody public Object read(@PathVariable Long id,Authentication a,@RequestParam(defaultValue="0") long after){return reviews.read(id,current.require(a),after,false,null);}
 @PostMapping("/admin/support-reviews/{id}/export") @ResponseBody public org.springframework.http.ResponseEntity<Object> export(@PathVariable Long id,Authentication a,@RequestParam String reason,@RequestParam(defaultValue="0") long after){return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=chat-review-"+id+".json").header("Cache-Control","no-store").body(reviews.read(id,current.require(a),after,true,reason));}
 @GetMapping("/admin/support-reviews/{id}/documents") @ResponseBody public Object documents(@PathVariable Long id,Authentication a,@RequestParam(defaultValue="0") long after){return reviews.documents(id,current.require(a),after);}
 @GetMapping("/admin/support-reviews/{id}/documents/{documentId}/download") public org.springframework.http.ResponseEntity<org.springframework.core.io.Resource> document(@PathVariable Long id,@PathVariable Long documentId,Authentication a){var d=reviews.download(id,documentId,current.require(a));return org.springframework.http.ResponseEntity.ok().contentType(org.springframework.http.MediaType.APPLICATION_OCTET_STREAM).header("X-Content-Type-Options","nosniff").header("Cache-Control","no-store").header("Content-Disposition",org.springframework.http.ContentDisposition.attachment().filename(d.getOriginalName(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(storage.resource(d.getStorageKey()));}
 @GetMapping("/admin/support-reviews/{id}/audit") @ResponseBody public Object audit(@PathVariable Long id,Authentication a){return reviews.audit(id,current.require(a));}
}
